ALTER TABLE public.locations ADD COLUMN IF NOT EXISTS zelle_email text;

UPDATE public.locations SET card_payment_url = 'https://secure.cardknox.com/goldstarrestorationnj', zelle_email = 'HeshyL@GoldStarRestoration.com' WHERE code = 'NJ';
UPDATE public.locations SET card_payment_url = 'https://secure.cardknox.com/goldstarrestorationca' WHERE code = 'CA';

DELETE FROM public.email_templates WHERE key IN ('send_invoice','send_estimate','send_forms_signature','send_invoice_cash','payment_received','insurance_estimate','invoice_follow_up_1','tenant_forms');

INSERT INTO public.email_templates (key, name, category, subject, body, is_active, intake_form) VALUES
('send_invoice', 'Send Invoice', 'invoice',
 '{Job.JobNumber} {Job.JobName} {Job.SiteAddress.Address1}',
 '<p>Hello {Job.CustomerName},</p><p>Please see the attached invoice for the work completed at: {Job.SiteAddress.Address1} {Job.SiteAddress.City}, {Job.SiteAddress.State} {Job.SiteAddress.PostalCode}</p><p>We are pleased to offer several convenient methods for payment:</p><ul><li><b>Cash/Check:</b> We accept cash and check to {Office - Company Name}. Payment is due upon the due date noted on the invoice.</li><li><b>Credit/Debit Card Payments:</b> Gold Star Restoration accepts credit and debit card payments through its secure payment site. Now you can pay your invoice conveniently at: {Office Payment Link} Please note: There will be a credit card processing fee added to all credit card transactions.</li><li><b>Chase QuickPay:</b> Please send any QuickPay/Zelle payments to {Office Zelle Email}</li></ul><p>Should you have any questions, please feel free to reach out to us and we would be happy to help.</p>', true, false),
('send_estimate', 'Send Estimate', 'estimate',
 '{Office - Company Name} – Estimate',
 '<p>Greetings,</p><p>Thank you for contacting {Office - Company Name}. I''ve attached your estimate for your project.</p><p>Please reply to this email or call me if you have any questions.</p>', true, false),
('send_forms_signature', 'Send Forms with Signature', 'work_authorization',
 '{Job.SiteAddress.Address1} – Gold Star Restoration - Job #{Job.JobNumber}',
 '<p>Hello {Form Recipient Full Name},</p><p>Please review and complete the required form(s) related to Job #{Job.JobNumber} by clicking the link below:</p><p>Signing Link: {{link}}</p><p>If you have any questions or need help accessing the forms, please feel free to contact us.</p><p>We appreciate your prompt attention.</p>', true, true),
('send_invoice_cash', 'Send Invoice – Cash', 'invoice',
 '{Job.JobNumber} {Job.JobName} {Job.SiteAddress.Address1}',
 '<p>Dear {Job.BillingName},</p><p>Thank you for choosing {Office - Company Name} for your restoration needs. In accordance with our agreement, we have attached an invoice for services provided at your property and are ready to process your payment.</p><p>Please use the secure payment link below to complete the payment of {Invoice Total} for the services provided: {Payment Link}</p><p>For your reference:</p><ul><li>Invoice Number: {Invoice Number}</li><li>Invoice Date: {Invoice Date}</li><li>Amount Due: {Invoice Total}</li><li>Due Date: {Invoice Due Date}</li></ul><p>We are pleased to offer several convenient methods for payment:</p><ul><li><b>Cash/Check:</b> We accept cash and check to {Office - Company Name}. Payment is due upon the due date noted on the invoice.</li><li><b>Credit/Debit Card Payments:</b> Gold Star Restoration accepts credit and debit card payments through its secure payment site. Now you can pay your invoice conveniently at: {Office Payment Link} Please note: There will be a credit card processing fee added to all credit card transactions.</li><li><b>Chase QuickPay:</b> Please send any QuickPay/Zelle payments to {Office Zelle Email}</li></ul><p>If you have any questions, please feel free to contact us.</p><p>Thank you for your prompt attention to this matter.</p><p>Best regards,</p>', true, false),
('payment_received', 'Payment Received – Thank You!', 'notification',
 'Payment Received – Thank You!',
 '<p>Hello {Job.CustomerName},</p><p>Thank you for your payment! We''ve successfully received payment for Invoice #{Invoice Number}.</p><p>If you have any questions or need further assistance, feel free to reach out to us at {Office Phone} or {Office Email}.</p><p>We appreciate your business and would like to thank you for choosing {Office - Company Name} for all your restoration and mitigation needs.</p>', true, false),
('insurance_estimate', 'Insurance Estimate', 'estimate',
 'Claim #: {Job.ClaimNumber}, {Job.SiteAddress.Address1}, {Job.SiteAddress.City}, {Job.SiteAddress.State} {Job.SiteAddress.PostalCode}',
 '<p>Greetings,</p><p>Please see the attached invoice for emergency mitigation services provided at: {Job.SiteAddress.Address1}, {Job.SiteAddress.City}, {Job.SiteAddress.State} {Job.SiteAddress.PostalCode}</p><p>Policy Number: {Job.PolicyNumber}, Claim Number: {Job.ClaimNumber}, DOL: {Job.LossDate}</p><p>Invoiced items included on the estimate from third parties are attached separately.</p><p>Thank you!</p>', true, false),
('invoice_follow_up_1', 'Invoice Follow Up – 1', 'follow_up',
 'Invoice Follow Up',
 '<p>Hi {Job.CustomerName},</p><p>This is a friendly reminder regarding your outstanding invoice for the services performed by {Office - Company Name} at: {Job.SiteAddress.Address1}, {Job.SiteAddress.City}, {Job.SiteAddress.State} {Job.SiteAddress.PostalCode}</p><ul><li><b>Cash/Check:</b> We accept cash and check to {Office - Company Name}. Payment is due upon the due date noted on the invoice.</li><li><b>Credit/Debit Card Payments:</b> Gold Star Restoration accepts credit and debit card payments through its secure payment site. Now you can pay your invoice conveniently at: {Office Payment Link} Please note: There will be a credit card processing fee added to all credit card transactions.</li><li><b>Chase QuickPay:</b> Please send any QuickPay/Zelle payments to {Office Zelle Email}</li></ul><p>Please remit payment at your earliest convenience. Now you can pay your invoice conveniently by credit card and Zelle. Please check your invoice for details. Should you not have your invoice, please reply to this email and it will be resent.</p><p>Thank you for your prompt attention to this matter.</p>', true, false),
('tenant_forms', 'Tenant Forms', 'work_authorization',
 'Tenant Forms – Signature needed',
 '<p>Hi,</p><p>Please find the attached forms that must be signed by the tenant(s) in order for us to proceed with work in their units.</p><p>If you have any questions, please feel free to reach out.</p><p>Thank you.</p>', true, false);